-- Gym Progress exercise catalogue + e1RM friend comparison
-- Generated from GymProgress_Exercise_Catalogue_Review_v1_Response.xlsx
-- BACK UP THE SUPABASE PROJECT BEFORE RUNNING. See SUPABASE_BACKUP_BEFORE_EXERCISE_MIGRATION.md.

begin;
create extension if not exists pgcrypto;
create table if not exists public.exercise_families (
  id uuid primary key,
  key text not null unique,
  status text not null default 'ACTIVE' check (status in ('ACTIVE','DEPRECATED')),
  superseded_by uuid references public.exercise_families(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.canonical_exercises (
  id uuid primary key,
  key text not null unique,
  family_id uuid references public.exercise_families(id),
  equipment text not null,
  dumbbell_load text not null default 'SINGLE',
  exercise_type text not null,
  load_semantics text not null,
  comparison_eligible boolean not null default false,
  comparison_metric text,
  status text not null default 'ACTIVE' check (status in ('ACTIVE','DEPRECATED')),
  superseded_by uuid references public.canonical_exercises(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.canonical_exercise_translations (
  exercise_id uuid not null references public.canonical_exercises(id) on delete cascade,
  language_code text not null,
  name text not null,
  primary key (exercise_id, language_code)
);
create table if not exists public.canonical_exercise_aliases (
  id uuid primary key default gen_random_uuid(),
  exercise_id uuid not null references public.canonical_exercises(id) on delete cascade,
  language_code text not null,
  alias text not null,
  unique(exercise_id, language_code, alias)
);
create table if not exists public.catalogue_candidates (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references public.profiles(id) on delete set null,
  suggested_name text not null,
  equipment text,
  family_key text,
  load_semantics text,
  metadata jsonb not null default '{}'::jsonb,
  proposed_canonical_match uuid references public.canonical_exercises(id),
  review_status text not null default 'PENDING' check (review_status in ('PENDING','MATCHED','APPROVED_NEW','REJECTED')),
  created_at timestamptz not null default now(),
  reviewed_at timestamptz
);
create table if not exists public.exercise_comparison_points (
  id uuid primary key default gen_random_uuid(),
  client_point_id text not null,
  user_id uuid not null references public.profiles(id) on delete cascade,
  canonical_exercise_id uuid not null references public.canonical_exercises(id),
  occurred_at timestamptz not null,
  e1rm_kg numeric not null check (e1rm_kg > 0),
  formula_version text not null default 'EPLEY_RIR_V1',
  source_programme_exercise_ids text[] not null default '{}',
  source_labels text[] not null default '{}',
  created_at timestamptz not null default now(),
  unique(user_id, client_point_id)
);
create index if not exists exercise_comparison_points_user_exercise_time_idx on public.exercise_comparison_points(user_id, canonical_exercise_id, occurred_at);

-- Catalogue is public read-only application data. Only privileged/admin SQL should modify it.
alter table public.exercise_families enable row level security;
alter table public.canonical_exercises enable row level security;
alter table public.canonical_exercise_translations enable row level security;
alter table public.canonical_exercise_aliases enable row level security;
alter table public.catalogue_candidates enable row level security;
alter table public.exercise_comparison_points enable row level security;

drop policy if exists exercise_families_read on public.exercise_families;
create policy exercise_families_read on public.exercise_families for select using (true);
drop policy if exists canonical_exercises_read on public.canonical_exercises;
create policy canonical_exercises_read on public.canonical_exercises for select using (true);
drop policy if exists canonical_exercise_translations_read on public.canonical_exercise_translations;
create policy canonical_exercise_translations_read on public.canonical_exercise_translations for select using (true);
drop policy if exists canonical_exercise_aliases_read on public.canonical_exercise_aliases;
create policy canonical_exercise_aliases_read on public.canonical_exercise_aliases for select using (true);

drop policy if exists catalogue_candidates_own_insert on public.catalogue_candidates;
create policy catalogue_candidates_own_insert on public.catalogue_candidates for insert with check (auth.uid() = user_id);
drop policy if exists catalogue_candidates_own_read on public.catalogue_candidates;
create policy catalogue_candidates_own_read on public.catalogue_candidates for select using (auth.uid() = user_id);

drop policy if exists comparison_points_own_write on public.exercise_comparison_points;
create policy comparison_points_own_write on public.exercise_comparison_points for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists comparison_points_friend_read on public.exercise_comparison_points;
create policy comparison_points_friend_read on public.exercise_comparison_points for select using (auth.uid() = user_id or public.social_is_friend(auth.uid(), user_id));


-- Replace the signed-in user's derived comparison history atomically. This makes
-- programme-occurrence opt-in, unlink/relink, and catalogue corrections retroactive
-- without leaving stale social comparison points behind.
create or replace function public.social_replace_exercise_comparison_points(p_points jsonb default '[]'::jsonb)
returns integer
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_count integer := 0;
begin
  if v_uid is null then
    raise exception 'Authentication required';
  end if;
  if jsonb_typeof(coalesce(p_points, '[]'::jsonb)) <> 'array' then
    raise exception 'p_points must be a JSON array';
  end if;

  delete from public.exercise_comparison_points where user_id = v_uid;

    client_point_id,user_id,canonical_exercise_id,occurred_at,e1rm_kg,formula_version,
    source_programme_exercise_ids,source_labels
  )
  select
    item->>'client_point_id',
    v_uid,
    c.id,
    (item->>'occurred_at')::timestamptz,
    (item->>'e1rm_kg')::numeric,
    coalesce(nullif(item->>'formula_version',''),'EPLEY_RIR_V1'),
    array(select jsonb_array_elements_text(coalesce(item->'source_programme_exercise_ids','[]'::jsonb))),
    array(select jsonb_array_elements_text(coalesce(item->'source_labels','[]'::jsonb)))
  from jsonb_array_elements(coalesce(p_points,'[]'::jsonb)) item
  join public.canonical_exercises c
    on c.id=(item->>'canonical_exercise_id')::uuid
   and c.comparison_eligible=true
  where coalesce(item->>'client_point_id','')<>''
    and coalesce((item->>'e1rm_kg')::numeric,0)>0
  on conflict(user_id,client_point_id) do update set
    canonical_exercise_id=excluded.canonical_exercise_id,
    occurred_at=excluded.occurred_at,
    e1rm_kg=excluded.e1rm_kg,
    formula_version=excluded.formula_version,
    source_programme_exercise_ids=excluded.source_programme_exercise_ids,
    source_labels=excluded.source_labels;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

create or replace function public.social_common_comparable_exercises(p_friend_id uuid)
returns table(canonical_exercise_id uuid, name_en text, name_lv text)
language sql stable security definer set search_path = public, pg_temp as $$
  select c.id, en.name, lv.name
  from public.canonical_exercises c
  join public.canonical_exercise_translations en on en.exercise_id=c.id and en.language_code='en'
  left join public.canonical_exercise_translations lv on lv.exercise_id=c.id and lv.language_code='lv'
  where c.comparison_eligible = true
    and public.social_is_friend(auth.uid(), p_friend_id)
    and exists(select 1 from public.exercise_comparison_points p where p.user_id=auth.uid() and p.canonical_exercise_id=c.id)
    and exists(select 1 from public.exercise_comparison_points p where p.user_id=p_friend_id and p.canonical_exercise_id=c.id)
  order by lower(en.name);
$$;

create or replace function public.social_exercise_comparison(p_friend_id uuid, p_canonical_exercise_id uuid, p_since timestamptz default null)
returns table(user_id uuid, occurred_at timestamptz, e1rm_kg numeric, formula_version text, source_labels text[])
language sql stable security definer set search_path = public, pg_temp as $$
  select p.user_id,p.occurred_at,p.e1rm_kg,p.formula_version,p.source_labels
  from public.exercise_comparison_points p
  where public.social_is_friend(auth.uid(),p_friend_id)
    and p.canonical_exercise_id=p_canonical_exercise_id
    and p.user_id in (auth.uid(),p_friend_id)
    and (p_since is null or p.occurred_at>=p_since)
  order by p.occurred_at,p.user_id;
$$;
-- Explicit API privileges. RLS above remains authoritative.
revoke all on public.exercise_families, public.canonical_exercises, public.canonical_exercise_translations, public.canonical_exercise_aliases from anon, authenticated;
grant select on public.exercise_families, public.canonical_exercises, public.canonical_exercise_translations, public.canonical_exercise_aliases to anon, authenticated;

revoke all on public.catalogue_candidates, public.exercise_comparison_points from anon, authenticated;
grant select, insert on public.catalogue_candidates to authenticated;
grant select, insert, update, delete on public.exercise_comparison_points to authenticated;

revoke execute on function public.social_replace_exercise_comparison_points(jsonb) from public, anon;
revoke execute on function public.social_common_comparable_exercises(uuid) from public, anon;
revoke execute on function public.social_exercise_comparison(uuid, uuid, timestamptz) from public, anon;
grant execute on function public.social_replace_exercise_comparison_points(jsonb) to authenticated;
grant execute on function public.social_common_comparable_exercises(uuid) to authenticated;
grant execute on function public.social_exercise_comparison(uuid, uuid, timestamptz) to authenticated;

commit;
